-- AssembleHeads (generated by build_heads.py): run once in Studio's command bar, after importing
-- NC_Head_Male.fbx, NC_Head_Female.fbx and every NC_Head_<Gender>_Hair<n>.fbx and _Cards<n>.fbx with the 3D Importer. Select all the
-- imported models (or just the ones you re-imported), paste this, press Enter.
-- The pieces go to ReplicatedStorage.NC_HeadAssets.<Gender>, where NCHead (the Character Studio) finds them.
local Selection = game:GetService("Selection")
local RS = game:GetService("ReplicatedStorage")
local root = RS:FindFirstChild("NC_HeadAssets") or Instance.new("Folder")
root.Name = "NC_HeadAssets"
root.Parent = RS
local done = 0
-- hair cards: the strand normal and roughness maps. If the 3D Importer didn't bring them in, upload
-- textures_heads/NC_HairCard_Normal.png and NC_HairCard_Rough.png and paste their rbxassetid:// ids here.
local CARD_NORMAL = ""
local CARD_ROUGH = ""
for _, model in ipairs(Selection:Get()) do
	local gender = model.Name:match("NC_Head_(%a+)")
	if not gender then
		warn("AssembleHeads: keep NC_Head_<Gender> in the name of " .. model.Name)
		continue
	end
	-- (the pieces come in several files: NC_Head_<Gender>.fbx and NC_Head_<Gender>_Cards<n>.fbx, so each piece
	--  replaces its old copy by name and the rest of the folder stays)
	local folder = root:FindFirstChild(gender)
	if not folder then
		folder = Instance.new("Folder")
		folder.Name = gender
	end
	for _, part in ipairs(model:GetDescendants()) do
		if part:IsA("MeshPart") then
			part.Anchored = false
			part.CanCollide, part.CanTouch, part.CanQuery, part.Massless = false, false, false, true
			part.CastShadow = false
			-- full detail at every distance: the automatic level of detail swaps in a coarse mesh further away, which
			-- showed the hair as a hard-edged cap with no fade
			pcall(function()
				part.RenderFidelity = Enum.RenderFidelity.Precise
			end)
			-- hair, brows and stubble keep their greyscale texture as a SurfaceAppearance with soft alpha
			local sa = part:FindFirstChildOfClass("SurfaceAppearance")
			if not sa and part.TextureID ~= "" then
				sa = Instance.new("SurfaceAppearance")
				sa.ColorMap = part.TextureID
				sa.Parent = part
			end
			part.TextureID = ""
			local isCards = part.Name:match("_Cards$") or part.Name:match("_CapCards$") or part.Name:match("_Cards_%d+$") or part.Name:match("_CapCards_%d+$")
			if sa then
				sa.AlphaMode = Enum.AlphaMode.Transparency
				if isCards then
					-- cards keep the strand normal/roughness so light runs along the hair
					if CARD_NORMAL ~= "" then sa.NormalMap = CARD_NORMAL end
					if CARD_ROUGH ~= "" then sa.RoughnessMap = CARD_ROUGH end
					sa.MetalnessMap = ""
				else
					sa.NormalMap, sa.RoughnessMap, sa.MetalnessMap = "", "", ""
				end
			end
			-- a card is one thin ribbon: seen from behind it must still draw
			part.DoubleSided = isCards and true or false
			for _, ch in ipairs(part:GetChildren()) do
				if not (ch:IsA("Attachment") or ch == sa) then
					ch:Destroy()
				end
			end
			local prev = folder:FindFirstChild(part.Name)
			if prev then
				prev:Destroy()
			end
			part.Parent = folder
			done += 1
		end
	end
	folder.Parent = root
	model:Destroy()
end
-- drop pieces a newer build no longer makes (NCHead would still wear them): anything not listed in NCHeadData
local removed = 0
local okData, data = pcall(function()
	local m = RS:FindFirstChild("NCHeadData")
	return m and require(m:Clone())
end)
if okData and data then
	for _, folder in ipairs(root:GetChildren()) do
		local listed = data[folder.Name] and data[folder.Name].pieces
		if listed then
			for _, part in ipairs(folder:GetChildren()) do
				if part:IsA("MeshPart") and not listed[part.Name] then
					part:Destroy()
					removed += 1
				end
			end
		end
	end
else
	warn("AssembleHeads: update ReplicatedStorage.NCHeadData first, then run this again to remove old pieces")
end
print("AssembleHeads: " .. done .. " hair and face pieces ready in ReplicatedStorage.NC_HeadAssets, " .. removed .. " old ones removed")
